    // while still iterating over all k per (x, y). Reordering to
    //   for y (parallel)
    //     for k
    //       for x (vectorized)
    // preserves semantics because each (x, y) reduction over k is independent.
    gemm.update()
        .reorder(x, k, y)  // loops (outermost -> innermost): y, k, x
        .parallel(y)
        .vectorize(x, vec_width);

    // Compile the kernel to machine code (JIT) with the chosen target
    gemm.compile_jit(target);

